// AU3 (docs/16_AUDIO.md §2.3): the makeup-gain compensation table that
// replaces applyCharacter()'s old, wrong `1 + 0.4 * c.comp` (finding 4 --
// on top of DynamicsCompressorNode's own automatic makeup gain and the
// -3dB pad, that line is why Vinyl played louder than Pure).
//
// MAKEUP_TABLE below is generated by scripts/derive-makeup-table.mjs, not
// hand-written: it renders the real Vinyl chain (pad -> wobble -> sat ->
// satTrim -> dc -> tone -> comp -> makeup) at unity makeup gain across a
// grid of c.comp, measures BS.1770 integrated loudness, and solves for
// the exact dB of makeup gain that would close the gap to Pure's own
// (unprocessed) loudness -- see that script's own header for the full
// derivation and why one unity-gain render per sample point is enough
// (a gain change shifts BS.1770 loudness by exactly 20*log10(gain) dB).
// Re-run it after any change to the pad/sat/tone/comp formulas in
// src/audio/engine.js's buildGraph()/applyCharacter(), since this table
// would otherwise silently drift out of sync with the chain it was
// measured against.
//
// c.sat and c.soft aren't separate table axes: the three named Character
// presets (src/wiring/character.js) move sat/soft/comp together in a
// fairly consistent ratio, and the derivation script samples them from
// that same ratio at every comp point, so a single comp-indexed table
// already captures the presets' own shape -- see the script's own
// satOf()/softOf() comments for the exact fit.

// MAKEUP_TABLE_START (generated by scripts/derive-makeup-table.mjs -- do not hand-edit)
const MAKEUP_TABLE = [
  { comp: 0, makeupDb: 3.644 },
  { comp: 0.05, makeupDb: 3.792 },
  { comp: 0.1, makeupDb: 3.778 },
  { comp: 0.15, makeupDb: 3.663 },
  { comp: 0.2, makeupDb: 3.449 },
  { comp: 0.25, makeupDb: 3.144 },
  { comp: 0.3, makeupDb: 2.762 },
  { comp: 0.35, makeupDb: 2.327 },
  { comp: 0.4, makeupDb: 1.877 },
  { comp: 0.45, makeupDb: 1.439 },
  { comp: 0.5, makeupDb: 1.034 },
  { comp: 0.55, makeupDb: 0.677 },
  { comp: 0.6, makeupDb: 0.383 },
  { comp: 0.65, makeupDb: 0.164 },
  { comp: 0.7, makeupDb: 0.021 },
  { comp: 0.75, makeupDb: -0.05 },
  { comp: 0.8, makeupDb: -0.067 },
  { comp: 0.85, makeupDb: -0.051 },
  { comp: 0.9, makeupDb: -0.034 },
  { comp: 0.95, makeupDb: -0.003 },
  { comp: 1, makeupDb: 0.05 },
];
// MAKEUP_TABLE_END

function makeupDbForComp(comp){
  const c = Math.min(1, Math.max(0, comp));
  const table = MAKEUP_TABLE;
  if(table.length === 1) return table[0].makeupDb;
  for(let i = 1; i < table.length; i++){
    if(c <= table[i].comp){
      const a = table[i-1], b = table[i];
      const span = b.comp - a.comp;
      const f = span > 0 ? (c - a.comp) / span : 0;
      return a.makeupDb + (b.makeupDb - a.makeupDb) * f;
    }
  }
  return table[table.length - 1].makeupDb;
}

// makeupGainFor(c) -> linear gain for S.nodes.makeup, given the effective
// Character values applyCharacter() just computed ({wow, sat, soft, comp}).
// Keyed on c.comp alone -- see the module comment above for why.
export function makeupGainFor(c){
  return Math.pow(10, makeupDbForComp(c.comp) / 20);
}
